<?php
declare(strict_types=1);require_once __DIR__.'/access.php';require_login();$isAdmin=$_SESSION['user']['role']==='admin';if(!$isAdmin&&$_SESSION['user']['role']==='employee')require_permission('view_activity');$pdo=db();$selectedEmployee=(int)($_GET['employee_id']??0);$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$action=trim((string)($_GET['action']??''));$where=[];$params=[];if($isAdmin&&$selectedEmployee){$where[]='al.employee_id=?';$params[]=$selectedEmployee;}if($from){$where[]='DATE(al.created_at)>=?';$params[]=$from;}if($to){$where[]='DATE(al.created_at)<=?';$params[]=$to;}if($action){$where[]='al.action LIKE ?';$params[]='%'.$action.'%';}$where[]=$isAdmin?'1=1':'al.employee_id=?';if(!$isAdmin)$params[]=$_SESSION['user']['id'];$stmt=$pdo->prepare('SELECT al.*,u.name FROM activity_log al LEFT JOIN users u ON u.id=al.employee_id WHERE '.implode(' AND ',$where).' ORDER BY al.created_at DESC LIMIT 200');$stmt->execute($params);$logs=$stmt->fetchAll();$employees=$isAdmin?$pdo->query("SELECT id,name FROM users WHERE role='employee' ORDER BY name")->fetchAll():[];function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Activity Log</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="<?= $isAdmin?'admin_dashboard.php':'employee_dashboard.php'?>">▦ <span>Overview</span></a><a class="saas-nav active" href="activity_log.php">◌ <span>Activity log</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Activity Log</h1><form method="get" class="saas-card"><div class="row g-2"><?php if($isAdmin):?><div class="col-md-3"><select class="form-control" name="employee_id"><option value="0">All employees</option><?php foreach($employees as $person):?><option value="<?=$person['id']?>" <?=((int)$person['id']===$selectedEmployee)?'selected':''?>><?=e($person['name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-2"><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-2"><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-3"><input class="form-control" name="action" placeholder="Action type" value="<?=e($action)?>"></div><button class="btn-indigo">Filter</button></div></form><section class="saas-card"><table class="saas-table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Reference</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['name']??'System')?></td><td><?=e($log['action'])?></td><td><?=e($log['reference_type'].($log['reference_id']?' #'.$log['reference_id']:''))?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
